using CustomCodeFramework.Postgres.EntityFramework.Configurations;using Dhole.Content.Domain.Taxonomies.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace Dhole.Content.Persistence.Configurations.Taxonomies;internal sealed class TaxonomyTermConfiguration:EntityTypeConfigurationBase<TaxonomyTerm,Guid>{public override void Configure(EntityTypeBuilder<TaxonomyTerm>b){base.Configure(b);b.ToTable("taxonomy_terms");b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.SiteKey).HasMaxLength(80).IsRequired();b.Property(x=>x.Kind).HasMaxLength(30).IsRequired();b.Property(x=>x.Name).HasMaxLength(200).IsRequired();b.Property(x=>x.Slug).HasMaxLength(200).IsRequired();b.Property(x=>x.Description).HasMaxLength(1200);b.HasIndex(x=>new{x.SiteKey,x.Kind,x.Slug}).IsUnique().HasFilter("is_deleted = false");b.HasIndex(x=>new{x.SiteKey,x.Kind,x.SortOrder});}}
